-- Synthetic resort-style schema. ALL DATA IS FAKE and generated by db/seed.py.
-- Dates are ISO text ('YYYY-MM-DD'). Money is in SGD (REAL).
-- This file is also sent to the LLM as the schema, so the comments matter.

CREATE TABLE guests (
    guest_id      INTEGER PRIMARY KEY,
    full_name     TEXT NOT NULL,
    email         TEXT,                -- NULL when the guest gave no email
    country       TEXT NOT NULL,       -- country of residence
    loyalty_tier  TEXT NOT NULL,       -- Member | Silver | Gold | Platinum
    joined_date   TEXT NOT NULL        -- date the guest registered
);

CREATE TABLE bookings (
    booking_id    INTEGER PRIMARY KEY,
    guest_id      INTEGER NOT NULL REFERENCES guests(guest_id),
    room_type     TEXT NOT NULL,       -- Deluxe | Premier | Club | Suite
    check_in      TEXT NOT NULL,
    check_out     TEXT NOT NULL,
    nightly_rate  REAL NOT NULL,
    total_amount  REAL NOT NULL,       -- nights * nightly_rate
    status        TEXT NOT NULL        -- completed | cancelled | no_show
);

CREATE TABLE restaurants (
    restaurant_id INTEGER PRIMARY KEY,
    name          TEXT NOT NULL,
    cuisine       TEXT NOT NULL,
    location      TEXT NOT NULL,       -- where in the resort
    seats         INTEGER NOT NULL
);

CREATE TABLE orders (                  -- one row per restaurant bill
    order_id      INTEGER PRIMARY KEY,
    restaurant_id INTEGER NOT NULL REFERENCES restaurants(restaurant_id),
    guest_id      INTEGER REFERENCES guests(guest_id),   -- NULL for walk-in diners
    order_date    TEXT NOT NULL,
    party_size    INTEGER NOT NULL,
    amount        REAL NOT NULL        -- bill total
);

CREATE TABLE retail_sales (            -- one row per retail transaction
    sale_id       INTEGER PRIMARY KEY,
    store_name    TEXT NOT NULL,
    category      TEXT NOT NULL,       -- Fashion | Jewellery | Electronics | Cosmetics | Souvenirs
    sale_date     TEXT NOT NULL,
    quantity      INTEGER NOT NULL,
    amount        REAL NOT NULL,       -- transaction total
    guest_id      INTEGER REFERENCES guests(guest_id)    -- NULL when not linked to a guest
);

CREATE TABLE events (
    event_id      INTEGER PRIMARY KEY,
    event_name    TEXT NOT NULL,
    event_type    TEXT NOT NULL,       -- Concert | Conference | Exhibition | Gala
    venue         TEXT NOT NULL,
    event_date    TEXT NOT NULL,
    capacity      INTEGER NOT NULL,
    attendance    INTEGER,             -- NULL if not recorded
    ticket_price  REAL NOT NULL        -- price per ticket
);
